import {LocalitySearchIndex} from './locality-search-index.mjs';
let manifest,index,loading;
async function ready(){if(index)return index;if(!loading)loading=(async()=>{const response=await fetch(manifest.indexUrl);if(!response.ok)throw Error('Locality search unavailable');let bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());index=new LocalitySearchIndex(bytes,manifest);return index;})().catch(error=>{loading=null;throw error;});return loading;}
self.onmessage=async({data})=>{if(data.type==='init'){manifest=data.manifest;return;}try{const source=await ready(),start=performance.now(),result=data.type==='children'?source.children(data.parent,data.query,data.offset):source.search(data.query);self.postMessage({id:data.id,result,elapsed:performance.now()-start});}catch(error){self.postMessage({id:data.id,error:error.message});}};
